import { flush, init } from "neatlogs";
import { langchainHandler } from "neatlogs/langchain";

import { getServerEnv } from "@/lib/env";

let initializationPromise: Promise<void> | undefined;

export function initializeNeatlogs(): Promise<void> {
  initializationPromise ??= init({
    apiKey: getServerEnv().NEATLOGS_API_KEY,
    workflowName: "locke-agent",
    tags: ["neathack-2026"],
  });

  return initializationPromise;
}

export async function createNeatlogsHandler() {
  await initializeNeatlogs();
  return langchainHandler();
}

export async function flushNeatlogs(): Promise<boolean> {
  await initializeNeatlogs();
  return flush();
}

tools.description:
Retrieves a list of teams (teamspaces) in the current workspace. Shows which teams exist, user membership status, IDs, names, and roles.

Teams are returned split by membership status and limited to a maximum of 10 results.

<examples>
1. List all teams (up to the limit of each type): {}

2. Search for teams by name: {"query": "engineering"}

3. Find a specific team: {"query": "Product Design"}
</examples>

